package com.mfg.erp.entity;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.*;
/** ERP 生产订单：承接已确认销售需求，随后由 MES 执行。 */
@Entity @Table(name="erp_prod_order",catalog="src_erp") @Getter @Setter @NoArgsConstructor public class ProductionOrder{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="prod_order_no")private String prodOrderNo;@Column(name="sales_order_no")private String salesOrderNo;@Column(name="product_code")private String productCode;@Column(name="product_name")private String productName;@Column(name="plan_qty")private BigDecimal planQty;@Column(name="unit_code")private String unitCode;@Column(name="plan_start_date")private LocalDate planStartDate;@Column(name="plan_finish_date")private LocalDate planFinishDate;@Column(name="order_status")private String status="CREATED";@Column(name="bom_code")private String bomCode;@Column(name="bom_version")private String bomVersion;@Column(name="created_by")private String createdBy;}
